toolScript:
let isStrobing = false;
        let unit = 'rpm'; // or 'hz'
        let frequency = 10; // in Hz
        let dutyCycle = 0.1;
        let animationId;
        // Setup monitor Hz detection
        let monitorHz = 60;
        function detectHz() {
            let count = 0;
            let start = performance.now();
            function check(now) {
                count++;
                if (now - start >= 1000) {
                    monitorHz = count;
                    document.getElementById('monitor-hz').innerText = monitorHz;
                    return;
                }
                requestAnimationFrame(check);
            }
            requestAnimationFrame(check);
        }
        function syncInputs(val) {
            let num = parseFloat(val) || 0;
            if (unit === 'rpm') {
                frequency = num / 60;
            } else {
                frequency = num;
            }
            updateReadout();
        }
        function updateReadout() {
            const display = document.getElementById('main-readout');
            if (unit === 'rpm') {
                display.innerText = (frequency * 60).toFixed(2);
            } else {
                display.innerText = frequency.toFixed(2);
            }
        }
        function adjustFreq(delta) {
            const input = document.getElementById('freq-input');
            let val = parseFloat(input.value) || 0;
            if (delta === 0.5 || delta === 2) {
                val *= delta;
            } else {
                val += delta;
            }
            input.value = Math.max(0, val).toFixed(2);
            syncInputs(input.value);
        }
        function toggleUnits() {
            unit = document.getElementById('unit-toggle').value;
            const label = document.getElementById('unit-label');
            const input = document.getElementById('freq-input');
            if (unit === 'rpm') {
                label.innerText = "Revolutions Per Minute (RPM)";
                input.value = (frequency * 60).toFixed(2);
            } else {
                label.innerText = "Hertz (Cycles Per Second)";
                input.value = frequency.toFixed(2);
            }
            updateReadout();
        }
        function updateDuty(val) {
            dutyCycle = val / 100;
            document.getElementById('duty-val').innerText = val + "%";
        }
        function toggleStrobe() {
            const overlay = document.getElementById('strobe-overlay');
            const btn = document.getElementById('start-btn');
            if (isStrobing) {
                isStrobing = false;
                overlay.style.display = 'none';
                btn.classList.remove('bg-red-600', 'hover:bg-red-700');
                btn.classList.add('bg-cyan-600', 'hover:bg-cyan-700');
                btn.querySelector('span').innerText = "Initialize Full Screen Protocol";
                cancelAnimationFrame(animationId);
                if (document.exitFullscreen) document.exitFullscreen().catch(() => { });
            } else {
                if (frequency <= 0) return;
                isStrobing = true;
                overlay.style.display = 'block';
                btn.classList.remove('bg-cyan-600', 'hover:bg-cyan-700');
                btn.classList.add('bg-red-600', 'hover:bg-red-700');
                btn.querySelector('span').innerText = "TERMINATE STROBE (ESC)";
                if (document.documentElement.requestFullscreen) {
                    document.documentElement.requestFullscreen().catch(() => { });
                }
                runStrobeLoop();
            }
        }
        function runStrobeLoop() {
            const overlay = document.getElementById('strobe-overlay');
            const period = 1000 / frequency; // total ms per cycle
            const onDuration = period * dutyCycle;
            function loop(now) {
                if (!isStrobing) return;
                const elapsedInPeriod = now % period;
                if (elapsedInPeriod < onDuration) {
                    overlay.style.backgroundColor = 'white';
                } else {
                    overlay.style.backgroundColor = 'black';
                }
                animationId = requestAnimationFrame(loop);
            }
            animationId = requestAnimationFrame(loop);
        }
        // Handle Escape Key
        document.addEventListener('keydown', (e) => {
            if (e.key === "Escape" && isStrobing) toggleStrobe();
        });
        // Initialize Scroll to Top Logic
        // Start detection
        detectHz();
        // Set initial readout
        updateReadout();
